BEGIN;
-- Disable triggers/constraints for bulk load if needed
-- SET session_replication_role = 'replica'; -- Postgres

-- ASP.NET Core Identity tables (Postgres, quoted names to match EF Core defaults)
DROP TABLE IF EXISTS "AspNetUserTokens" CASCADE;
DROP TABLE IF EXISTS "AspNetUserRoles" CASCADE;
DROP TABLE IF EXISTS "AspNetUserLogins" CASCADE;
DROP TABLE IF EXISTS "AspNetUserClaims" CASCADE;
DROP TABLE IF EXISTS "AspNetRoleClaims" CASCADE;
DROP TABLE IF EXISTS "AspNetUsers" CASCADE;
DROP TABLE IF EXISTS "AspNetRoles" CASCADE;

DROP TABLE IF EXISTS donor_churn_scores CASCADE;
DROP TABLE IF EXISTS resident_reintegration_scores CASCADE;
DROP TABLE IF EXISTS safehouse_education_forecasts CASCADE;
DROP TABLE IF EXISTS social_media_conversion_predictions CASCADE;
DROP TABLE IF EXISTS pipeline_runs CASCADE;
DROP TABLE IF EXISTS social_media_posts CASCADE;
DROP TABLE IF EXISTS public_impact_snapshots CASCADE;
DROP TABLE IF EXISTS regional_risk_snapshots CASCADE;
DROP TABLE IF EXISTS safehouse_monthly_metrics CASCADE;
DROP TABLE IF EXISTS process_recordings CASCADE;
DROP TABLE IF EXISTS residents CASCADE;
DROP TABLE IF EXISTS safehouses CASCADE;
DROP TABLE IF EXISTS supporters CASCADE;

DROP TABLE IF EXISTS partner_assignments CASCADE;
DROP TABLE IF EXISTS donation_allocations CASCADE;
DROP TABLE IF EXISTS in_kind_donation_items CASCADE;
DROP TABLE IF EXISTS incident_reports CASCADE;
DROP TABLE IF EXISTS intervention_plans CASCADE;
DROP TABLE IF EXISTS home_visitations CASCADE;
DROP TABLE IF EXISTS health_wellbeing_records CASCADE;
DROP TABLE IF EXISTS education_records CASCADE;
DROP TABLE IF EXISTS donations CASCADE;
DROP TABLE IF EXISTS partners CASCADE;

-- Table: AspNetRoles
CREATE TABLE "AspNetRoles" (
    "Id" text PRIMARY KEY,
    "Name" character varying(256),
    "NormalizedName" character varying(256),
    "ConcurrencyStamp" text
);

-- Table: AspNetUsers
CREATE TABLE "AspNetUsers" (
    "Id" text PRIMARY KEY,
    "UserName" character varying(256),
    "NormalizedUserName" character varying(256),
    "Email" character varying(256),
    "NormalizedEmail" character varying(256),
    "EmailConfirmed" boolean NOT NULL,
    "PasswordHash" text,
    "SecurityStamp" text,
    "ConcurrencyStamp" text,
    "PhoneNumber" text,
    "PhoneNumberConfirmed" boolean NOT NULL,
    "TwoFactorEnabled" boolean NOT NULL,
    "LockoutEnd" timestamp with time zone,
    "LockoutEnabled" boolean NOT NULL,
    "AccessFailedCount" integer NOT NULL
);

-- Table: AspNetRoleClaims
CREATE TABLE "AspNetRoleClaims" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "RoleId" text NOT NULL,
    "ClaimType" text,
    "ClaimValue" text,
    CONSTRAINT "FK_AspNetRoleClaims_AspNetRoles_RoleId"
        FOREIGN KEY ("RoleId") REFERENCES "AspNetRoles" ("Id") ON DELETE CASCADE
);

-- Table: AspNetUserClaims
CREATE TABLE "AspNetUserClaims" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "UserId" text NOT NULL,
    "ClaimType" text,
    "ClaimValue" text,
    CONSTRAINT "FK_AspNetUserClaims_AspNetUsers_UserId"
        FOREIGN KEY ("UserId") REFERENCES "AspNetUsers" ("Id") ON DELETE CASCADE
);

-- Table: AspNetUserLogins
CREATE TABLE "AspNetUserLogins" (
    "LoginProvider" text NOT NULL,
    "ProviderKey" text NOT NULL,
    "ProviderDisplayName" text,
    "UserId" text NOT NULL,
    CONSTRAINT "PK_AspNetUserLogins" PRIMARY KEY ("LoginProvider", "ProviderKey"),
    CONSTRAINT "FK_AspNetUserLogins_AspNetUsers_UserId"
        FOREIGN KEY ("UserId") REFERENCES "AspNetUsers" ("Id") ON DELETE CASCADE
);

-- Table: AspNetUserRoles
CREATE TABLE "AspNetUserRoles" (
    "UserId" text NOT NULL,
    "RoleId" text NOT NULL,
    CONSTRAINT "PK_AspNetUserRoles" PRIMARY KEY ("UserId", "RoleId"),
    CONSTRAINT "FK_AspNetUserRoles_AspNetRoles_RoleId"
        FOREIGN KEY ("RoleId") REFERENCES "AspNetRoles" ("Id") ON DELETE CASCADE,
    CONSTRAINT "FK_AspNetUserRoles_AspNetUsers_UserId"
        FOREIGN KEY ("UserId") REFERENCES "AspNetUsers" ("Id") ON DELETE CASCADE
);

-- Table: AspNetUserTokens
CREATE TABLE "AspNetUserTokens" (
    "UserId" text NOT NULL,
    "LoginProvider" text NOT NULL,
    "Name" text NOT NULL,
    "Value" text,
    CONSTRAINT "PK_AspNetUserTokens" PRIMARY KEY ("UserId", "LoginProvider", "Name"),
    CONSTRAINT "FK_AspNetUserTokens_AspNetUsers_UserId"
        FOREIGN KEY ("UserId") REFERENCES "AspNetUsers" ("Id") ON DELETE CASCADE
);

-- Identity indexes
CREATE INDEX "IX_AspNetRoleClaims_RoleId" ON "AspNetRoleClaims" ("RoleId");
CREATE INDEX "IX_AspNetUserClaims_UserId" ON "AspNetUserClaims" ("UserId");
CREATE INDEX "IX_AspNetUserLogins_UserId" ON "AspNetUserLogins" ("UserId");
CREATE INDEX "IX_AspNetUserRoles_RoleId" ON "AspNetUserRoles" ("RoleId");
CREATE INDEX "EmailIndex" ON "AspNetUsers" ("NormalizedEmail");
CREATE UNIQUE INDEX "RoleNameIndex" ON "AspNetRoles" ("NormalizedName")
WHERE "NormalizedName" IS NOT NULL;
CREATE UNIQUE INDEX "UserNameIndex" ON "AspNetUsers" ("NormalizedUserName")
WHERE "NormalizedUserName" IS NOT NULL;

-- Seed identity roles
INSERT INTO "AspNetRoles" ("Id", "Name", "NormalizedName", "ConcurrencyStamp")
VALUES
    ('role-admin', 'Admin', 'ADMIN', 'seed-admin-role'),
    ('role-donor', 'Donor', 'DONOR', 'seed-donor-role')
ON CONFLICT ("Id") DO UPDATE SET
    "Name" = EXCLUDED."Name",
    "NormalizedName" = EXCLUDED."NormalizedName";

-- Seed default admin identity user
DO $$
DECLARE
    admin_user_id text;
BEGIN
    SELECT "Id"
    INTO admin_user_id
    FROM "AspNetUsers"
    WHERE "NormalizedUserName" = 'ADMIN@HOPEHARBOR.ORG'
    LIMIT 1;

    IF admin_user_id IS NULL THEN
        admin_user_id := 'user-admin';
        INSERT INTO "AspNetUsers" (
            "Id",
            "UserName",
            "NormalizedUserName",
            "Email",
            "NormalizedEmail",
            "EmailConfirmed",
            "PasswordHash",
            "SecurityStamp",
            "ConcurrencyStamp",
            "PhoneNumber",
            "PhoneNumberConfirmed",
            "TwoFactorEnabled",
            "LockoutEnd",
            "LockoutEnabled",
            "AccessFailedCount"
        ) VALUES (
            admin_user_id,
            'admin@hopeharbor.org',
            'ADMIN@HOPEHARBOR.ORG',
            'admin@hopeharbor.org',
            'ADMIN@HOPEHARBOR.ORG',
            TRUE,
            'AQAAAAIAAYagAAAAEBUrlMQBl0V8Li6CvYwAZfKAsA+f7xGHhElHtlINfGfk0M2pkOJeHckb1cnmwi5vgQ==',
            'seed-admin-security-stamp',
            'seed-admin-concurrency-stamp',
            NULL,
            FALSE,
            FALSE,
            NULL,
            TRUE,
            0
        );
    ELSE
        UPDATE "AspNetUsers"
        SET
            "UserName" = 'admin@hopeharbor.org',
            "NormalizedUserName" = 'ADMIN@HOPEHARBOR.ORG',
            "Email" = 'admin@hopeharbor.org',
            "NormalizedEmail" = 'ADMIN@HOPEHARBOR.ORG',
            "EmailConfirmed" = TRUE,
            "PasswordHash" = 'AQAAAAIAAYagAAAAEBUrlMQBl0V8Li6CvYwAZfKAsA+f7xGHhElHtlINfGfk0M2pkOJeHckb1cnmwi5vgQ==',
            "LockoutEnabled" = TRUE,
            "AccessFailedCount" = 0
        WHERE "Id" = admin_user_id;
    END IF;

    INSERT INTO "AspNetUserRoles" ("UserId", "RoleId")
    VALUES (admin_user_id, 'role-admin')
    ON CONFLICT ("UserId", "RoleId") DO NOTHING;
END $$;


