-- Table: health_wellbeing_records
CREATE TABLE health_wellbeing_records (
    health_record_id INT PRIMARY KEY,
    resident_id INT,
    record_date DATE,
    general_health_score DECIMAL(10, 5),
    nutrition_score DECIMAL(10, 5),
    sleep_quality_score DECIMAL(10, 5),
    energy_level_score DECIMAL(10, 5),
    height_cm DECIMAL(10, 5),
    weight_kg DECIMAL(10, 5),
    bmi DECIMAL(10, 5),
    medical_checkup_done BOOLEAN,
    dental_checkup_done BOOLEAN,
    psychological_checkup_done BOOLEAN,
    notes TEXT
);
