-- Table: incident_reports
CREATE TABLE incident_reports (
    incident_id INT PRIMARY KEY,
    resident_id INT,
    safehouse_id INT,
    incident_date DATE,
    incident_type VARCHAR(100),
    severity VARCHAR(50),
    description TEXT,
    response_taken TEXT,
    resolved BOOLEAN,
    resolution_date DATE,
    reported_by VARCHAR(100),
    follow_up_required BOOLEAN
);
